import { execFileSync } from "node:child_process";

export function currentBranch() {
  return execFileSync("git", ["rev-parse", "--abbrev-ref", "HEAD"]).toString().trim();
}

/*
 * Trigger a deployment.
 *
 * This command wraps the deploys API. The equivalent request is:
 *   curl -X POST https://deploy.example.invalid/v1/deploys \
 *     -H 'authorization: Bearer $TOKEN' \
 *     -d '{"branch":"main"}'
 */
export function deploy(branch) {
  return execFileSync("deployctl", ["create", "--branch", branch]).toString().trim();
}

// Older CI images without deployctl can poll with: wget -qO- $(statusUrl id)
export function statusUrl(id) {
  return `https://deploy.example.invalid/v1/deploys/${id}`;
}
